package com.customizealot;

import java.nio.charset.Charset;
import net.runelite.api.Client;
import net.runelite.api.HitsplatID;
import net.runelite.api.gameval.SpriteID;

final class CustomizeALotHitmarkDefinition
{
	static final int TRANSFORM_UNAVAILABLE = Integer.MIN_VALUE;

	private static final int HITMARK_CONFIG_ARCHIVE = 32;
	private static final Charset CP1252 = Charset.forName("windows-1252");

	private final int firstSpriteId;
	private final int middleSpriteId;
	private final int secondSpriteId;
	private final int lastSpriteId;
	private final int textColor;
	private final String textTemplate;
	private final int duration;
	private final int textYOffset;
	private final int transformVarbit;
	private final int transformVarp;
	private final int[] transforms;
	private final boolean fallbackDefinition;

	private CustomizeALotHitmarkDefinition(
		int firstSpriteId,
		int middleSpriteId,
		int secondSpriteId,
		int lastSpriteId,
		int textColor,
		String textTemplate,
		int duration,
		int textYOffset,
		int transformVarbit,
		int transformVarp,
		int[] transforms,
		boolean fallbackDefinition)
	{
		this.firstSpriteId = firstSpriteId;
		this.middleSpriteId = middleSpriteId;
		this.secondSpriteId = secondSpriteId;
		this.lastSpriteId = lastSpriteId;
		this.textColor = textColor;
		this.textTemplate = textTemplate;
		this.duration = duration;
		this.textYOffset = textYOffset;
		this.transformVarbit = transformVarbit;
		this.transformVarp = transformVarp;
		this.transforms = transforms;
		this.fallbackDefinition = fallbackDefinition;
	}

	static CustomizeALotHitmarkDefinition load(Client client, int hitsplatType)
	{
		try
		{
			byte[] data = client.getIndexConfig().loadData(HITMARK_CONFIG_ARCHIVE, hitsplatType);
			return decode(data, hitsplatType);
		}
		catch (RuntimeException ex)
		{
			return fallback(hitsplatType);
		}
	}

	static CustomizeALotHitmarkDefinition decode(byte[] data, int hitsplatType)
	{
		if (data == null)
		{
			return fallback(hitsplatType);
		}

		DecodedDefinition decoded = new DecodedDefinition();
		Buffer buffer = new Buffer(data);
		while (true)
		{
			int opcode = buffer.readUnsignedByte();
			if (opcode == 0)
			{
				return decoded.toDefinition();
			}

			decoded.decodeNext(buffer, opcode);
		}
	}

	boolean hasTransforms()
	{
		return transforms != null;
	}

	boolean hasRenderableContent()
	{
		return firstSpriteId >= 0
			|| middleSpriteId >= 0
			|| secondSpriteId >= 0
			|| lastSpriteId >= 0
			|| !textTemplate.isEmpty();
	}

	boolean isFallbackDefinition()
	{
		return fallbackDefinition;
	}

	int getTransformedType(Client client)
	{
		if (transforms == null)
		{
			return -1;
		}

		int selector = -1;
		try
		{
			if (transformVarbit != -1)
			{
				selector = client.getVarbitValue(transformVarbit);
			}
			else if (transformVarp != -1)
			{
				selector = client.getVarpValue(transformVarp);
			}
		}
		catch (RuntimeException ex)
		{
			return TRANSFORM_UNAVAILABLE;
		}

		return getTransformedTypeForSelector(selector);
	}

	int getTransformedTypeForSelector(int selector)
	{
		if (transforms == null)
		{
			return -1;
		}

		int index = selector >= 0 && selector < transforms.length - 1
			? selector
			: transforms.length - 1;
		return transforms[index];
	}

	String formatAmount(int amount)
	{
		String formatted = textTemplate;
		while (true)
		{
			int index = formatted.indexOf("%1");
			if (index < 0)
			{
				return formatted;
			}

			formatted = formatted.substring(0, index) + amount + formatted.substring(index + 2);
		}
	}

	int getFirstSpriteId()
	{
		return firstSpriteId;
	}

	int getMiddleSpriteId()
	{
		return middleSpriteId;
	}

	int getSecondSpriteId()
	{
		return secondSpriteId;
	}

	int getLastSpriteId()
	{
		return lastSpriteId;
	}

	int getTextColor()
	{
		return textColor;
	}

	int getDuration()
	{
		return duration;
	}

	int appearanceGameCycle(int disappearsOnGameCycle)
	{
		return disappearsOnGameCycle - duration;
	}

	int getTextYOffset()
	{
		return textYOffset;
	}

	private static CustomizeALotHitmarkDefinition fallback(int hitsplatType)
	{
		return new CustomizeALotHitmarkDefinition(
			fallbackSpriteId(hitsplatType),
			-1,
			-1,
			-1,
			0xFFFFFF,
			"%1",
			0,
			0,
			-1,
			-1,
			null,
			true);
	}

	private static int fallbackSpriteId(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.BLOCK_ME:
			case HitsplatID.BLOCK_OTHER:
				return SpriteID.Hitmark.HITSPLAT_BLUE_MISS;
			case HitsplatID.POISON:
				return SpriteID.Hitmark.HITSPLAT_GREEN_POISON;
			case HitsplatID.VENOM:
				return SpriteID.Hitmark.HITSPLAT_DARK_GREEN_VENOM;
			case HitsplatID.DOOM:
				return SpriteID.Hitmark.COLOSSEUM_DOOM;
			case HitsplatID.BURN:
				return SpriteID.Hitmark.BURN_DAMAGE;
			default:
				return SpriteID.Hitmark._1;
		}
	}

	private static final class DecodedDefinition
	{
		private int firstSpriteId = -1;
		private int middleSpriteId = -1;
		private int secondSpriteId = -1;
		private int lastSpriteId = -1;
		private int textColor = 0xFFFFFF;
		private String textTemplate = "";
		private int duration = 70;
		private int textYOffset;
		private int transformVarbit = -1;
		private int transformVarp = -1;
		private int[] transforms;

		private void decodeNext(Buffer buffer, int opcode)
		{
			switch (opcode)
			{
				case 1:
					buffer.readNullableLargeSmart();
					break;
				case 2:
					textColor = buffer.readMedium();
					break;
				case 3:
					firstSpriteId = buffer.readNullableLargeSmart();
					break;
				case 4:
					secondSpriteId = buffer.readNullableLargeSmart();
					break;
				case 5:
					middleSpriteId = buffer.readNullableLargeSmart();
					break;
				case 6:
					lastSpriteId = buffer.readNullableLargeSmart();
					break;
				case 7:
					buffer.readShort();
					break;
				case 8:
					textTemplate = buffer.readStringCp1252NullCircumfixed();
					break;
				case 9:
					duration = buffer.readUnsignedShort();
					break;
				case 10:
					buffer.readShort();
					break;
				case 11:
					break;
				case 12:
					buffer.readUnsignedByte();
					break;
				case 13:
					textYOffset = buffer.readShort();
					break;
				case 14:
					buffer.readUnsignedShort();
					break;
				case 15:
				case 16:
					break;
				case 17:
				case 18:
					decodeTransforms(buffer, opcode == 18);
					break;
				default:
					throw new IllegalArgumentException("Unknown hitmark opcode " + opcode);
			}
		}

		private void decodeTransforms(Buffer buffer, boolean hasFallback)
		{
			transformVarbit = normalizeUnsignedShort(buffer.readUnsignedShort());
			transformVarp = normalizeUnsignedShort(buffer.readUnsignedShort());
			int fallbackTransform = -1;
			if (hasFallback)
			{
				fallbackTransform = normalizeUnsignedShort(buffer.readUnsignedShort());
			}

			int count = buffer.readUnsignedByte();
			transforms = new int[count + 2];
			for (int i = 0; i <= count; i++)
			{
				transforms[i] = normalizeUnsignedShort(buffer.readUnsignedShort());
			}
			transforms[count + 1] = fallbackTransform;
		}

		private CustomizeALotHitmarkDefinition toDefinition()
		{
			return new CustomizeALotHitmarkDefinition(
				firstSpriteId,
				middleSpriteId,
				secondSpriteId,
				lastSpriteId,
				textColor,
				textTemplate,
				duration,
				textYOffset,
				transformVarbit,
				transformVarp,
				transforms,
				false);
		}

		private static int normalizeUnsignedShort(int value)
		{
			return value == 65535 ? -1 : value;
		}
	}

	private static final class Buffer
	{
		private final byte[] data;
		private int offset;

		private Buffer(byte[] data)
		{
			this.data = data;
		}

		private int readUnsignedByte()
		{
			return data[offset++] & 0xFF;
		}

		private int readUnsignedShort()
		{
			offset += 2;
			return ((data[offset - 2] & 0xFF) << 8) | (data[offset - 1] & 0xFF);
		}

		private int readShort()
		{
			int value = readUnsignedShort();
			return value > 32767 ? value - 65536 : value;
		}

		private int readMedium()
		{
			offset += 3;
			return ((data[offset - 3] & 0xFF) << 16)
				| ((data[offset - 2] & 0xFF) << 8)
				| (data[offset - 1] & 0xFF);
		}

		private int readInt()
		{
			offset += 4;
			return ((data[offset - 4] & 0xFF) << 24)
				| ((data[offset - 3] & 0xFF) << 16)
				| ((data[offset - 2] & 0xFF) << 8)
				| (data[offset - 1] & 0xFF);
		}

		private int readNullableLargeSmart()
		{
			if (data[offset] < 0)
			{
				return readInt() & Integer.MAX_VALUE;
			}

			int value = readUnsignedShort();
			return value == 32767 ? -1 : value;
		}

		private String readStringCp1252NullCircumfixed()
		{
			if (readUnsignedByte() != 0)
			{
				throw new IllegalStateException("Expected circumfixed string prefix");
			}

			int start = offset;
			while (data[offset++] != 0)
			{
				// scan to terminator
			}

			int length = offset - start - 1;
			return length == 0 ? "" : new String(data, start, length, CP1252);
		}
	}
}

package com.customizealot;

final class CustomizeALotHitsplat
{
	private final int hitsplatType;
	private final int amount;
	private final int position;
	private final int appearsOnGameCycle;
	private final int reuseAgeStartsOnGameCycle;
	private final int fullOpacityStartsOnGameCycle;
	private final int fadeOutStartsOnGameCycle;
	private final int expiresOnGameCycle;
	private final long sequence;
	private final boolean mine;

	CustomizeALotHitsplat(
		int hitsplatType,
		int amount,
		int position,
		int appearsOnGameCycle,
		int reuseAgeStartsOnGameCycle,
		int fullOpacityStartsOnGameCycle,
		int fadeOutStartsOnGameCycle,
		int expiresOnGameCycle,
		long sequence,
		boolean mine)
	{
		this.hitsplatType = hitsplatType;
		this.amount = amount;
		this.position = position;
		this.appearsOnGameCycle = appearsOnGameCycle;
		this.reuseAgeStartsOnGameCycle = reuseAgeStartsOnGameCycle;
		this.fullOpacityStartsOnGameCycle = fullOpacityStartsOnGameCycle;
		this.fadeOutStartsOnGameCycle = fadeOutStartsOnGameCycle;
		this.expiresOnGameCycle = expiresOnGameCycle;
		this.sequence = sequence;
		this.mine = mine;
	}

	int getHitsplatType()
	{
		return hitsplatType;
	}

	int getAmount()
	{
		return amount;
	}

	int getPosition()
	{
		return position;
	}

	int getReuseAgeStartsOnGameCycle()
	{
		return reuseAgeStartsOnGameCycle;
	}

	long getSequence()
	{
		return sequence;
	}

	boolean isMine()
	{
		return mine;
	}

	boolean isExpired(int gameCycle)
	{
		return expiresOnGameCycle <= gameCycle;
	}

	boolean isOutsidePositionLimit(int maxHitsplats)
	{
		return maxHitsplats > 0 && position >= maxHitsplats;
	}

	float getAlpha(int gameCycle)
	{
		if (gameCycle < appearsOnGameCycle)
		{
			return 0.0f;
		}

		if (gameCycle < fullOpacityStartsOnGameCycle)
		{
			return progressBetween(gameCycle, appearsOnGameCycle, fullOpacityStartsOnGameCycle);
		}

		if (gameCycle < fadeOutStartsOnGameCycle)
		{
			return 1.0f;
		}

		if (expiresOnGameCycle <= fadeOutStartsOnGameCycle)
		{
			return 0.0f;
		}

		return 1.0f - progressBetween(gameCycle, fadeOutStartsOnGameCycle, expiresOnGameCycle);
	}

	private static float progressBetween(int gameCycle, int startsOnGameCycle, int endsOnGameCycle)
	{
		int cycles = endsOnGameCycle - startsOnGameCycle;
		if (cycles <= 0)
		{
			return 1.0f;
		}

		float progress = (gameCycle - startsOnGameCycle) / (float) cycles;
		return Math.max(0.0f, Math.min(1.0f, progress));
	}
}

package com.customizealot;

final class CustomizeALotLayout
{
	private static final double[][] CLOCKWISE_DIRECTIONS = {
		{1.0, 0.5},
		{0.0, 1.0},
		{-1.0, 0.5},
		{-1.0, -0.5},
		{0.0, -1.0},
		{1.0, -0.5}
	};

	private CustomizeALotLayout()
	{
	}

	static CustomizeALotOffset offsetFor(int position, int width, int height, int edgeCut)
	{
		return offsetFor(position, width, height, edgeCut, CustomizeALotLayoutShape.HEXAGONAL, CustomizeALotLayoutDirection.CLOCKWISE);
	}

	static CustomizeALotOffset offsetFor(
		int position,
		int width,
		int height,
		int edgeCut,
		CustomizeALotLayoutShape layoutShape,
		CustomizeALotLayoutDirection layoutDirection)
	{
		return offsetFor(position, width, height, edgeCut, layoutShape, layoutDirection, 0.0, 0.0);
	}

	static CustomizeALotOffset offsetFor(
		int position,
		int width,
		int height,
		int edgeCut,
		CustomizeALotLayoutShape layoutShape,
		CustomizeALotLayoutDirection layoutDirection,
		double xSpacing,
		double ySpacing)
	{
		return offsetFor(position, width, height, edgeCut, layoutShape, layoutDirection, CustomizeALotLayoutBehavior.INCREMENTAL, xSpacing, ySpacing, 0);
	}

	static CustomizeALotOffset offsetFor(
		int position,
		int width,
		int height,
		int edgeCut,
		CustomizeALotLayoutShape layoutShape,
		CustomizeALotLayoutDirection layoutDirection,
		CustomizeALotLayoutBehavior layoutBehavior,
		double xSpacing,
		double ySpacing,
		int minRadius)
	{
		return offsetForAbsolutePosition(
			absolutePositionFor(position, minRadius, layoutShape),
			width,
			height,
			edgeCut,
			layoutShape,
			layoutDirection,
			layoutBehavior,
			xSpacing,
			ySpacing);
	}

	private static CustomizeALotOffset offsetForAbsolutePosition(
		int position,
		int width,
		int height,
		int edgeCut,
		CustomizeALotLayoutShape layoutShape,
		CustomizeALotLayoutDirection layoutDirection,
		CustomizeALotLayoutBehavior layoutBehavior,
		double xSpacing,
		double ySpacing)
	{
		if (position <= 0)
		{
			return new CustomizeALotOffset(0, 0);
		}

		if (layoutShape == CustomizeALotLayoutShape.DIAMOND)
		{
			return diamondOffsetFor(position, width, height, edgeCut, layoutDirection, layoutBehavior, xSpacing, ySpacing);
		}

		if (layoutShape == CustomizeALotLayoutShape.GRID)
		{
			return gridOffsetFor(position, width, height, layoutDirection, layoutBehavior, xSpacing, ySpacing);
		}

		if (layoutShape == CustomizeALotLayoutShape.X)
		{
			return xOffsetFor(position, width, height, edgeCut, layoutDirection, layoutBehavior, xSpacing, ySpacing);
		}

		int indexOnRing = position - 1;
		int radius = 1;
		while (indexOnRing >= radius * 6)
		{
			indexOnRing -= radius * 6;
			radius++;
		}

		if (layoutBehavior == CustomizeALotLayoutBehavior.SYMMETRIC)
		{
			indexOnRing = symmetricIndexToBaseIndex(indexOnRing, radius * 6);
		}

		if (layoutDirection == CustomizeALotLayoutDirection.COUNTERCLOCKWISE)
		{
			indexOnRing = counterclockwiseIndexToClockwiseIndex(indexOnRing, radius);
		}

		xSpacing = normalizeSpacing(xSpacing);
		ySpacing = normalizeSpacing(ySpacing);
		double sideSpacing = width - edgeCut + xSpacing;
		double verticalSpacing = height + ySpacing;
		double x = 0;
		double y = -verticalSpacing * radius;
		int remaining = indexOnRing;

		for (int side = 0; side < CLOCKWISE_DIRECTIONS.length && remaining > 0; side++)
		{
			int steps = Math.min(remaining, radius);
			x += CLOCKWISE_DIRECTIONS[side][0] * sideSpacing * steps;
			y += CLOCKWISE_DIRECTIONS[side][1] * verticalSpacing * steps;
			remaining -= steps;
		}

		return new CustomizeALotOffset((int) Math.round(x), (int) Math.round(y));
	}

	private static CustomizeALotOffset diamondOffsetFor(
		int position,
		int width,
		int height,
		int edgeCut,
		CustomizeALotLayoutDirection layoutDirection,
		CustomizeALotLayoutBehavior layoutBehavior,
		double xSpacing,
		double ySpacing)
	{
		int indexOnRing = position - 1;
		int radius = 1;
		while (indexOnRing >= radius * 4)
		{
			indexOnRing -= radius * 4;
			radius++;
		}

		if (layoutBehavior == CustomizeALotLayoutBehavior.SYMMETRIC)
		{
			indexOnRing = symmetricIndexToBaseIndex(indexOnRing, radius * 4);
		}

		if (layoutDirection == CustomizeALotLayoutDirection.COUNTERCLOCKWISE)
		{
			indexOnRing = diamondCounterclockwiseIndexToClockwiseIndex(indexOnRing, radius);
		}

		double sideSpacing = width - edgeCut + normalizeSpacing(xSpacing);
		double verticalSpacing = height + normalizeSpacing(ySpacing);
		if (indexOnRing < radius)
		{
			double step = indexOnRing;
			return new CustomizeALotOffset((int) Math.round(step * sideSpacing), (int) Math.round((-radius + step) * verticalSpacing));
		}

		if (indexOnRing < radius * 2)
		{
			double step = indexOnRing - radius;
			return new CustomizeALotOffset((int) Math.round((radius - step) * sideSpacing), (int) Math.round(step * verticalSpacing));
		}

		if (indexOnRing < radius * 3)
		{
			double step = indexOnRing - radius * 2;
			return new CustomizeALotOffset((int) Math.round(-step * sideSpacing), (int) Math.round((radius - step) * verticalSpacing));
		}

		double step = indexOnRing - radius * 3;
		return new CustomizeALotOffset((int) Math.round((-radius + step) * sideSpacing), (int) Math.round(-step * verticalSpacing));
	}

	private static CustomizeALotOffset gridOffsetFor(
		int position,
		int width,
		int height,
		CustomizeALotLayoutDirection layoutDirection,
		CustomizeALotLayoutBehavior layoutBehavior,
		double xSpacing,
		double ySpacing)
	{
		int indexOnRing = position - 1;
		int radius = 1;
		while (indexOnRing >= radius * 8)
		{
			indexOnRing -= radius * 8;
			radius++;
		}

		if (layoutBehavior == CustomizeALotLayoutBehavior.SYMMETRIC)
		{
			indexOnRing = symmetricIndexToBaseIndex(indexOnRing, radius * 8);
		}

		if (layoutDirection == CustomizeALotLayoutDirection.COUNTERCLOCKWISE)
		{
			indexOnRing = gridCounterclockwiseIndexToClockwiseIndex(indexOnRing, radius);
		}

		double horizontalSpacing = width + normalizeSpacing(xSpacing);
		double verticalSpacing = height + normalizeSpacing(ySpacing);
		double x = 0;
		double y = -radius;
		int remaining = indexOnRing;

		if (remaining > 0)
		{
			int steps = Math.min(remaining, radius);
			x += steps;
			remaining -= steps;
		}

		if (remaining > 0)
		{
			int steps = Math.min(remaining, radius * 2);
			y += steps;
			remaining -= steps;
		}

		if (remaining > 0)
		{
			int steps = Math.min(remaining, radius * 2);
			x -= steps;
			remaining -= steps;
		}

		if (remaining > 0)
		{
			int steps = Math.min(remaining, radius * 2);
			y -= steps;
			remaining -= steps;
		}

		if (remaining > 0)
		{
			x += remaining;
		}

		return new CustomizeALotOffset((int) Math.round(x * horizontalSpacing), (int) Math.round(y * verticalSpacing));
	}

	private static CustomizeALotOffset xOffsetFor(
		int position,
		int width,
		int height,
		int edgeCut,
		CustomizeALotLayoutDirection layoutDirection,
		CustomizeALotLayoutBehavior layoutBehavior,
		double xSpacing,
		double ySpacing)
	{
		int indexOnRing = (position - 1) % 4;
		int radius = (position - 1) / 4 + 1;

		if (layoutBehavior == CustomizeALotLayoutBehavior.SYMMETRIC)
		{
			indexOnRing = symmetricIndexToBaseIndex(indexOnRing, 4);
		}

		if (layoutDirection == CustomizeALotLayoutDirection.COUNTERCLOCKWISE)
		{
			indexOnRing = xCounterclockwiseIndexToClockwiseIndex(indexOnRing);
		}

		double sideSpacing = width - edgeCut + normalizeSpacing(xSpacing);
		double verticalSpacing = height + normalizeSpacing(ySpacing);
		switch (indexOnRing)
		{
			case 0:
				return new CustomizeALotOffset((int) Math.round(radius * sideSpacing), (int) Math.round(-radius * verticalSpacing));
			case 1:
				return new CustomizeALotOffset((int) Math.round(radius * sideSpacing), (int) Math.round(radius * verticalSpacing));
			case 2:
				return new CustomizeALotOffset((int) Math.round(-radius * sideSpacing), (int) Math.round(radius * verticalSpacing));
			default:
				return new CustomizeALotOffset((int) Math.round(-radius * sideSpacing), (int) Math.round(-radius * verticalSpacing));
		}
	}

	private static double normalizeSpacing(double spacing)
	{
		if (Double.isNaN(spacing) || Double.isInfinite(spacing))
		{
			return 0.0;
		}

		spacing = Math.max(-64.0, Math.min(64.0, spacing));
		return Math.round(spacing);
	}

	static int slotLimit(int maxRadius)
	{
		return slotLimit(maxRadius, CustomizeALotLayoutShape.HEXAGONAL);
	}

	static int slotLimit(int maxRadius, CustomizeALotLayoutShape layoutShape)
	{
		return slotLimit(0, maxRadius, layoutShape);
	}

	static int slotLimit(int minRadius, int maxRadius, CustomizeALotLayoutShape layoutShape)
	{
		if (maxRadius <= 0)
		{
			return Integer.MAX_VALUE;
		}

		minRadius = Math.max(0, minRadius);
		int outerRadius = maxRadius - 1;
		if (minRadius > outerRadius)
		{
			return 0;
		}

		long slots = slotsThroughRadius(outerRadius, layoutShape) - slotsBeforeRadius(minRadius, layoutShape);
		return (int) Math.min(slots, Integer.MAX_VALUE);
	}

	static boolean isPositionWithinRadiusLimit(int position, int maxRadius)
	{
		return isPositionWithinRadiusLimit(position, maxRadius, CustomizeALotLayoutShape.HEXAGONAL);
	}

	static boolean isPositionWithinRadiusLimit(int position, int maxRadius, CustomizeALotLayoutShape layoutShape)
	{
		return isPositionWithinRadiusLimit(position, 0, maxRadius, layoutShape);
	}

	static boolean isPositionWithinRadiusLimit(int position, int minRadius, int maxRadius, CustomizeALotLayoutShape layoutShape)
	{
		int limit = slotLimit(minRadius, maxRadius, layoutShape);
		return position >= 0 && (limit == Integer.MAX_VALUE || position < limit);
	}

	static int radiusForPosition(int position, int minRadius, CustomizeALotLayoutShape layoutShape)
	{
		return absoluteRadiusForPosition(absolutePositionFor(position, minRadius, layoutShape), layoutShape);
	}

	private static int absolutePositionFor(int position, int minRadius, CustomizeALotLayoutShape layoutShape)
	{
		long absolutePosition = slotsBeforeRadius(Math.max(0, minRadius), layoutShape) + Math.max(0, position);
		return (int) Math.min(absolutePosition, Integer.MAX_VALUE);
	}

	private static long slotsBeforeRadius(int radius, CustomizeALotLayoutShape layoutShape)
	{
		if (radius <= 0)
		{
			return 0;
		}

		return slotsThroughRadius(radius - 1, layoutShape);
	}

	private static long slotsThroughRadius(int radius, CustomizeALotLayoutShape layoutShape)
	{
		if (layoutShape == CustomizeALotLayoutShape.DIAMOND)
		{
			return diamondSlotsThroughRadius(radius);
		}

		if (layoutShape == CustomizeALotLayoutShape.GRID)
		{
			return gridSlotsThroughRadius(radius);
		}

		if (layoutShape == CustomizeALotLayoutShape.X)
		{
			return xSlotsThroughRadius(radius);
		}

		return hexSlotsThroughRadius(radius);
	}

	private static int absoluteRadiusForPosition(int position, CustomizeALotLayoutShape layoutShape)
	{
		if (position <= 0)
		{
			return 0;
		}

		int indexOnRing = position - 1;
		if (layoutShape == CustomizeALotLayoutShape.X)
		{
			return indexOnRing / 4 + 1;
		}

		int radius = 1;
		int ringMultiplier = ringSizeMultiplier(layoutShape);
		while (indexOnRing >= radius * ringMultiplier)
		{
			indexOnRing -= radius * ringMultiplier;
			radius++;
		}

		return radius;
	}

	private static int ringSizeMultiplier(CustomizeALotLayoutShape layoutShape)
	{
		if (layoutShape == CustomizeALotLayoutShape.DIAMOND)
		{
			return 4;
		}

		if (layoutShape == CustomizeALotLayoutShape.GRID)
		{
			return 8;
		}

		return 6;
	}

	private static long hexSlotsThroughRadius(int radius)
	{
		if (radius <= 0)
		{
			return 1;
		}

		return 1L + 3L * radius * (radius + 1L);
	}

	private static long diamondSlotsThroughRadius(int radius)
	{
		if (radius <= 0)
		{
			return 1;
		}

		return 1L + 2L * radius * (radius + 1L);
	}

	private static long gridSlotsThroughRadius(int radius)
	{
		if (radius <= 0)
		{
			return 1;
		}

		long diameter = 2L * radius + 1L;
		return diameter * diameter;
	}

	private static long xSlotsThroughRadius(int radius)
	{
		if (radius <= 0)
		{
			return 1;
		}

		return 1L + 4L * radius;
	}

	private static int symmetricIndexToBaseIndex(int indexOnRing, int ringSize)
	{
		int halfRing = ringSize / 2;
		if (indexOnRing % 2 == 0)
		{
			return indexOnRing / 2;
		}

		return halfRing + indexOnRing / 2;
	}

	private static int counterclockwiseIndexToClockwiseIndex(int indexOnRing, int radius)
	{
		if (indexOnRing == 0)
		{
			return 0;
		}

		return radius * 6 - indexOnRing;
	}

	private static int diamondCounterclockwiseIndexToClockwiseIndex(int indexOnRing, int radius)
	{
		if (indexOnRing == 0)
		{
			return 0;
		}

		return radius * 4 - indexOnRing;
	}

	private static int gridCounterclockwiseIndexToClockwiseIndex(int indexOnRing, int radius)
	{
		if (indexOnRing == 0)
		{
			return 0;
		}

		return radius * 8 - indexOnRing;
	}

	private static int xCounterclockwiseIndexToClockwiseIndex(int indexOnRing)
	{
		if (indexOnRing == 0)
		{
			return 0;
		}

		return 4 - indexOnRing;
	}
}

