	static int chatLaneTop(
		int actorTopY,
		int ascent,
		CustomizeALotOverheadChatEffect effect)
	{
		return actorTopY
			+ COMPONENT_GAP
			- Math.max(0, ascent)
			- effectVerticalPadding(effect);
	}

	static int chatBaseline(int actorTopY, int yOffset)
	{
