		drawAbsoluteRoundedReference(
			expected,
			x,
			y,
			width,
			height,
			fillWidth,
			cornerRadius,
			borderThickness,
			front,
			back,
			border);

		Graphics2D graphics = actual.createGraphics();
		try
		{
			CustomizeALotHealthBarRenderer.drawCustomBar(
				graphics,
				x, y, width, height, fillWidth,
				CustomizeALotHealthBarFillDirection.LEFT_TO_RIGHT,
				CustomizeALotHealthBarGradient.SOLID,
				front, front,
				CustomizeALotHealthBarGradient.SOLID,
				back, back,
				0.5,
				border,
				borderThickness,
				cornerRadius);
		}
		finally
		{
			graphics.dispose();
		}

		assertArrayEquals(
			expected.getRGB(0, 0, expected.getWidth(), expected.getHeight(), null, 0, expected.getWidth()),
			actual.getRGB(0, 0, actual.getWidth(), actual.getHeight(), null, 0, actual.getWidth()));
	}

	private static void fillImage(BufferedImage image, Color color)
	{
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setColor(color);
			graphics.fillRect(0, 0, image.getWidth(), image.getHeight());
		}
		finally
		{
			graphics.dispose();
		}
	}

	private static BufferedImage renderCoordinateMode(
		CustomizeALotHealthBarGradientCoordinates coordinates)
	{
		return renderCoordinateMode(coordinates, coordinates);
	}

	private static BufferedImage renderCoordinateMode(
		CustomizeALotHealthBarGradientCoordinates frontCoordinates,
		CustomizeALotHealthBarGradientCoordinates backCoordinates)
	{
		BufferedImage image = new BufferedImage(10, 3, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			CustomizeALotHealthBarRenderer.drawCustomBar(
				graphics,
				0.0, 0.0, 10.0, 3.0, 5.0,
				CustomizeALotHealthBarFillDirection.LEFT_TO_RIGHT,
				CustomizeALotHealthBarGradient.HORIZONTAL,
				Color.RED, Color.BLUE,
				CustomizeALotHealthBarGradient.HORIZONTAL,
				Color.RED, Color.BLUE,
				0.5,
				frontCoordinates,
				backCoordinates,
				5.0,
				new Color(0, 0, 0, 0),
				0,
				1,
				new Color(0, 0, 0, 0),
				0.0,
				new Color(0, 0, 0, 0),
				0.0,
				0.0);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static BufferedImage renderHealthBased(
		boolean front,
		double healthFraction,
		Color first,
		Color second)
	{
		BufferedImage image = new BufferedImage(4, 3, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			CustomizeALotHealthBarRenderer.drawCustomBar(
				graphics,
				0.0, 0.0, 4.0, 3.0, front ? 4.0 : 0.0,
				CustomizeALotHealthBarFillDirection.LEFT_TO_RIGHT,
				CustomizeALotHealthBarGradient.HEALTH_BASED,
				first, second,
				CustomizeALotHealthBarGradient.HEALTH_BASED,
				first, second,
				healthFraction,
				CustomizeALotHealthBarGradientCoordinates.FULL_BAR,
				CustomizeALotHealthBarGradientCoordinates.SEGMENT,
				front ? 4.0 : 0.0,
				new Color(0, 0, 0, 0),
				0,
				1,
				new Color(0, 0, 0, 0),
				0.0,
				new Color(0, 0, 0, 0),
				0.0,
				0.0);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static int alpha(int argb)
	{
		return argb >>> 24;
	}

	private static void assertTruePartialAlpha(int argb)
	{
		int alpha = alpha(argb);
		assertEquals(true, alpha > 0 && alpha < 255);
	}

	private static void drawAbsoluteRoundedReference(
		BufferedImage image,
		int x,
		int y,
		int width,
		int height,
		int fillWidth,
		int cornerRadius,
		int borderThickness,
		Color front,
		Color back,
		Color border)
	{
		Shape inner = new RoundRectangle2D.Double(
			x,
			y,
			width,
			height,
			cornerRadius * 2,
			cornerRadius * 2);
		Graphics2D barGraphics = image.createGraphics();
		try
		{
			enableShapeAntialiasing(barGraphics);
			Area backArea = new Area(inner);
			backArea.intersect(new Area(new Rectangle2D.Double(
				x + fillWidth, y, width - fillWidth, height)));
			barGraphics.setColor(back);
			barGraphics.fill(backArea);
			Area frontArea = new Area(inner);
			frontArea.intersect(new Area(new Rectangle2D.Double(x, y, fillWidth, height)));
			barGraphics.setColor(front);
			barGraphics.fill(frontArea);
		}
		finally
		{
			barGraphics.dispose();
		}

		Area borderArea = new Area(inner);
		borderArea.subtract(new Area(new RoundRectangle2D.Double(
			x + borderThickness,
			y + borderThickness,
			width - borderThickness * 2,
			height - borderThickness * 2,
			Math.max(0, cornerRadius - borderThickness) * 2,
			Math.max(0, cornerRadius - borderThickness) * 2)));
		Graphics2D borderGraphics = image.createGraphics();
		try
		{
			enableShapeAntialiasing(borderGraphics);
			borderGraphics.setColor(border);
			borderGraphics.fill(borderArea);
		}
		finally
		{
			borderGraphics.dispose();
		}
	}

	private static void enableShapeAntialiasing(Graphics2D graphics)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
	}
}

package com.customizealot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class CustomizeALotHitmarkDefinitionTest
{
	@Test
	public void decodesSpritesTextColorTemplateAndYOffset()
	{
		byte[] data = {
			2, 0x12, 0x34, 0x56,
			3, 0x01, 0x41,
			4, 0x01, 0x42,
			5, 0x01, 0x43,
			6, 0x01, 0x44,
			8, 0, 'H', 'i', 't', ' ', '%', '1', '!', 0,
			12, 1,
			13, (byte) 0xFF, (byte) 0xFB,
			0
		};

		CustomizeALotHitmarkDefinition definition = CustomizeALotHitmarkDefinition.decode(data, 0);

		assertEquals(321, definition.getFirstSpriteId());
		assertEquals(322, definition.getSecondSpriteId());
		assertEquals(323, definition.getMiddleSpriteId());
		assertEquals(324, definition.getLastSpriteId());
		assertEquals(0x123456, definition.getTextColor());
		assertEquals(-5, definition.getTextYOffset());
		assertEquals("Hit 27!", definition.formatAmount(27));
		assertFalse(definition.hasTransforms());
	}

	@Test
	public void opcode17PreservesSelectedMinusOneTransform()
	{
		byte[] data = {
			17,
			0, 7,
			(byte) 0xFF, (byte) 0xFF,
			1,
			0, 100,
			(byte) 0xFF, (byte) 0xFF,
			0
		};
		CustomizeALotHitmarkDefinition definition = CustomizeALotHitmarkDefinition.decode(data, 0);

		assertTrue(definition.hasTransforms());
		assertEquals(100, definition.getTransformedTypeForSelector(0));
		assertEquals(-1, definition.getTransformedTypeForSelector(1));
		assertEquals(-1, definition.getTransformedTypeForSelector(99));
		assertEquals(
			CustomizeALotHitmarkDefinition.TRANSFORM_UNAVAILABLE,
			definition.getTransformedType(null));
	}

	@Test
	public void opcode18UsesItsExplicitFallbackTransform()
	{
		byte[] data = {
			18,
			(byte) 0xFF, (byte) 0xFF,
			0, 9,
			0, 44,
			0,
			0, 55,
			0
		};
		CustomizeALotHitmarkDefinition definition = CustomizeALotHitmarkDefinition.decode(data, 0);

		assertEquals(55, definition.getTransformedTypeForSelector(0));
		assertEquals(44, definition.getTransformedTypeForSelector(1));
	}

	@Test
	public void opcode9DecodesDuration()
	{
		CustomizeALotHitmarkDefinition definition =
			CustomizeALotHitmarkDefinition.decode(new byte[]{9, 0x01, 0x2C, 0}, 0);

		assertEquals(300, definition.getDuration());
		assertEquals(700, definition.appearanceGameCycle(1000));
		assertEquals(700, CustomizeALotOverlay.nativeAppearanceGameCycle(definition, 1000, 900));
	}

	@Test
	public void cacheFailureUsesEventTimingSoReplacementRemainsVisible()
	{
		CustomizeALotHitmarkDefinition fallback =
			CustomizeALotHitmarkDefinition.decode(null, 0);

		assertTrue(fallback.isFallbackDefinition());
		assertEquals(900, CustomizeALotOverlay.nativeAppearanceGameCycle(fallback, 1000, 900));
		assertEquals(900, CustomizeALotOverlay.nativeAppearanceGameCycle(null, 1000, 900));
	}

	@Test
	public void validSpriteLessDefinitionStaysEmpty()
	{
		CustomizeALotHitmarkDefinition definition = CustomizeALotHitmarkDefinition.decode(new byte[]{0}, 0);

		assertEquals(-1, definition.getFirstSpriteId());
		assertEquals(-1, definition.getMiddleSpriteId());
		assertEquals(-1, definition.getSecondSpriteId());
		assertEquals(-1, definition.getLastSpriteId());
		assertEquals("", definition.formatAmount(27));
		assertEquals(70, definition.getDuration());
		assertFalse(definition.hasRenderableContent());
		assertFalse(definition.isFallbackDefinition());
	}

	@Test
	public void resolvesNestedTransformsAndPreservesHiddenTarget()
	{
		CustomizeALotHitmarkDefinition first = transformFallback(2);
		CustomizeALotHitmarkDefinition second = transformFallback(3);
		CustomizeALotHitmarkDefinition finalDefinition =
			CustomizeALotHitmarkDefinition.decode(new byte[]{8, 0, '%', '1', 0, 0}, 3);
		Map<Integer, CustomizeALotHitmarkDefinition> definitions = new HashMap<>();
		definitions.put(1, first);
		definitions.put(2, second);
		definitions.put(3, finalDefinition);

		assertSame(
			finalDefinition,
			CustomizeALotOverlay.resolveDefinition(1, null, definitions::get));
		assertNull(CustomizeALotOverlay.resolveDefinition(
			4,
			null,
			ignored -> transformFallback(-1)));
	}

	@Test
	public void acceptsNativeNoOpOpcodes()
	{
		CustomizeALotHitmarkDefinition definition =
			CustomizeALotHitmarkDefinition.decode(new byte[]{15, 16, 0}, 0);

		assertFalse(definition.isFallbackDefinition());
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsUnknownOpcodes()
	{
		CustomizeALotHitmarkDefinition.decode(new byte[]{99, 0}, 0);
	}

	private static CustomizeALotHitmarkDefinition transformFallback(int target)
	{
		int encodedTarget = target < 0 ? 65535 : target;
		return CustomizeALotHitmarkDefinition.decode(new byte[]{
			18,
			(byte) 0xFF, (byte) 0xFF,
			(byte) 0xFF, (byte) 0xFF,
			(byte) (encodedTarget >>> 8), (byte) encodedTarget,
			0,
			(byte) 0xFF, (byte) 0xFF,
			0
		}, 0);
	}
}

package com.customizealot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class CustomizeALotHitsplatTest
{
	@Test
	public void fadesInThenHoldsThenFadesOut()
	{
		CustomizeALotHitsplat hitsplat = new CustomizeALotHitsplat(0, 10, 0, 100, 100, 120, 160, 180, 0, true);

		assertEquals(0.0f, hitsplat.getAlpha(100), 0.001f);
		assertEquals(0.5f, hitsplat.getAlpha(110), 0.001f);
		assertEquals(1.0f, hitsplat.getAlpha(120), 0.001f);
		assertEquals(1.0f, hitsplat.getAlpha(150), 0.001f);
		assertEquals(0.5f, hitsplat.getAlpha(170), 0.001f);
		assertEquals(0.0f, hitsplat.getAlpha(180), 0.001f);
		assertFalse(hitsplat.isExpired(179));
		assertTrue(hitsplat.isExpired(180));
		assertFalse(hitsplat.isOutsidePositionLimit(0));
		assertFalse(hitsplat.isOutsidePositionLimit(1));

		CustomizeALotHitsplat secondPosition =
			new CustomizeALotHitsplat(0, 10, 1, 100, 100, 120, 160, 180, 1, true);
		assertTrue(secondPosition.isOutsidePositionLimit(1));
	}
}

